import horizon

def parse(line):
    """'volume = 75' -> ('volume', 75.0). Positions count from 0."""
    eq = horizon.string.find(line, "=")
    if eq < 0:
        return None
    key = horizon.string.trim(horizon.string.substring(line, 0, eq))
    rest = horizon.string.substring(line, eq + 1, horizon.string.length(line))
    return key, horizon.string.toNumber(rest)

class Settings(horizon.Behavior):
    def on_start(self):
        parsed = parse("volume = 75")
        if parsed:
            key, value = parsed
            horizon.log(f"{key} is {value}")

import horizon

class PauseMenu(horizon.Behavior):
    # "Pause" is an input action with "Fires while the game is paused"
    # ticked; without it the second press would never arrive.
    def on_input_pressed(self, name):
        if name != "Pause":
            return
        if horizon.time.isPaused():
            horizon.time.resume()
        else:
            horizon.time.pause()

    def on_collision_enter(self, other):
        horizon.time.hitStop(0.1)   # a landed hit freezes for a tenth of a second

import horizon

class Reminders(horizon.Behavior):
    def on_start(self):
        self.autosave = horizon.timer.every(30)
        self.hint = horizon.timer.after(5)

    def on_timer(self, handle):
        if handle == self.autosave:
            horizon.log("autosave")
        elif handle == self.hint:
            horizon.log("Press E to open the door")
        # any other handle belongs to another script
